   237→    protected virtual bool ValidateWithdrawals(Block block, IReleaseSpec spec, out string? error)
   238→    {
   239→        if (spec.WithdrawalsEnabled && block.Withdrawals is null)
   240→        {
   241→            error = BlockErrorMessages.MissingWithdrawals;
   242→
   243→            if (_logger.IsWarn) _logger.Warn($"Withdrawals cannot be null in block {block.Hash} when EIP-4895 activated.");
   244→
   245→            return false;
   246→        }
   247→
   248→        if (!spec.WithdrawalsEnabled && block.Withdrawals is not null)
   249→        {
   250→            error = BlockErrorMessages.WithdrawalsNotEnabled;
   251→
   252→            if (_logger.IsWarn) _logger.Warn($"Withdrawals must be null in block {block.Hash} when EIP-4895 not activated.");
   253→
   254→            return false;
   255→        }
   256→
   257→        if (block.Withdrawals is not null)
   258→        {
   259→            if (!ValidateWithdrawalsHashMatches(block, out Hash256 withdrawalsRoot))
   260→            {
   261→                error = BlockErrorMessages.InvalidWithdrawalsRoot(block.Header.WithdrawalsRoot, withdrawalsRoot);
   262→                if (_logger.IsWarn) _logger.Warn($"Withdrawals root hash mismatch in block {block.ToString(Block.Format.FullHashAndNumber)}: expected {block.Header.WithdrawalsRoot}, got {withdrawalsRoot}");
   263→
   264→                return false;
   265→            }
   266→        }
   267→
   268→        error = null;
   269→
   270→        return true;
   271→    }
   272→
   273→    protected virtual bool ValidateTransactions(Block block, IReleaseSpec spec, out string? errorMessage)
   274→    {
   275→        Transaction[] transactions = block.Transactions;
   276→
   277→        for (int txIndex = 0; txIndex < transactions.Length; txIndex++)
   278→        {
   279→            Transaction transaction = transactions[txIndex];
   280→
   281→            ValidationResult isWellFormed = _txValidator.IsWellFormed(transaction, spec);
   282→            if (!isWellFormed)
   283→            {
   284→                if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Invalid transaction: {isWellFormed}");
   285→                errorMessage = isWellFormed.Error;
   286→                return false;
   287→            }
   288→        }
   289→        errorMessage = null;
   290→        return true;
   291→    }
   292→
   293→    protected virtual bool ValidateEip4844Fields(Block block, IReleaseSpec spec, out string? error)
   294→    {
   295→        if (!spec.IsEip4844Enabled)
   296→        {
   297→            error = null;
   298→            return true;
   299→        }
   300→
   301→        int blobsInBlock = 0;
   302→        UInt256 feePerBlobGas = UInt256.Zero;
   303→        Transaction[] transactions = block.Transactions;
   304→
   305→        for (int txIndex = 0; txIndex < transactions.Length; txIndex++)
   306→        {
   307→            Transaction transaction = transactions[txIndex];
   308→
   309→            if (!transaction.SupportsBlobs)
   310→            {
   311→                continue;
   312→            }
   313→
   314→            if (feePerBlobGas.IsZero)
   315→            {
   316→                if (!BlobGasCalculator.TryCalculateFeePerBlobGas(block.Header, spec.BlobBaseFeeUpdateFraction, out feePerBlobGas))
   317→                {
   318→                    error = BlockErrorMessages.BlobGasPriceOverflow;
   319→                    if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} {error}.");
   320→                    return false;
   321→                }
   322→            }
   323→
   324→            if (transaction.MaxFeePerBlobGas < feePerBlobGas)
   325→            {
   326→                error = BlockErrorMessages.InsufficientMaxFeePerBlobGas;
   327→                if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Transaction at index {txIndex} has insufficient {nameof(transaction.MaxFeePerBlobGas)} to cover current blob gas fee: {transaction.MaxFeePerBlobGas} < {feePerBlobGas}.");
   328→                return false;
   329→            }
   330→
   331→            blobsInBlock += transaction.BlobVersionedHashes!.Length;
   332→        }
   333→
   334→        ulong blobGasUsed = BlobGasCalculator.CalculateBlobGas(blobsInBlock);
   335→
   336→        if (blobGasUsed > spec.GetMaxBlobGasPerBlock())
   337→        {
   338→            error = BlockErrorMessages.BlobGasUsedAboveBlockLimit(spec.GetMaxBlobGasPerBlock(), blobsInBlock, blobGasUsed);
   339→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} {error}.");
   340→            return false;
   341→        }
   342→
   343→        if (blobGasUsed != block.Header.BlobGasUsed)
   344→        {
   345→            error = BlockErrorMessages.HeaderBlobGasMismatch(blobGasUsed, block.Header.BlobGasUsed);
   346→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} {nameof(BlockHeader.BlobGasUsed)} declared in the block header does not match actual blob gas used: {block.Header.BlobGasUsed} != {blobGasUsed}.");
   347→            return false;
   348→        }
   349→
   350→        error = null;
   351→        return true;
   352→    }
   353→
   354→    public bool ValidateBodyAgainstHeader(BlockHeader header, BlockBody toBeValidated) =>
   355→        ValidateBodyAgainstHeader(header, toBeValidated, out _);
   356→
   357→    public virtual bool ValidateBodyAgainstHeader(BlockHeader header, BlockBody toBeValidated, out string? errorMessage)
   358→    {
   359→        if (!ValidateTxRootMatchesTxs(header, toBeValidated, out Hash256? txRoot))
   360→        {
   361→            errorMessage = BlockErrorMessages.InvalidTxRoot(header.TxRoot, txRoot);
   362→            return false;
   363→        }
   364→
   365→        if (!ValidateUnclesHashMatches(header, toBeValidated, out _))
   366→        {
   367→            errorMessage = BlockErrorMessages.InvalidUnclesHash;
   368→            return false;
   369→        }
   370→
   371→        if (!ValidateWithdrawalsHashMatches(header, toBeValidated, out Hash256? withdrawalsRoot))
   372→        {
   373→            errorMessage = BlockErrorMessages.InvalidWithdrawalsRoot(header.WithdrawalsRoot, withdrawalsRoot);
   374→            return false;
   375→        }
   376→
   377→        errorMessage = null;
   378→        return true;
   379→    }
   380→
   381→    public static bool ValidateTxRootMatchesTxs(Block block, out Hash256 txRoot) =>
   382→        ValidateTxRootMatchesTxs(block.Header, block.Body, out txRoot);
   383→
   384→    public static bool ValidateTxRootMatchesTxs(BlockHeader header, BlockBody body, out Hash256 txRoot) =>
   385→        (txRoot = TxTrie.CalculateRoot(body.Transactions)) == header.TxRoot;
   386→
   387→    public static bool ValidateUnclesHashMatches(Block block, out Hash256 unclesHash) =>
   388→        ValidateUnclesHashMatches(block.Header, block.Body, out unclesHash);
   389→
   390→    public static bool ValidateUnclesHashMatches(BlockHeader header, BlockBody body, out Hash256 unclesHash) =>
   391→        (unclesHash = UnclesHash.Calculate(body.Uncles)) == header.UnclesHash;
   392→
   393→    public static bool ValidateWithdrawalsHashMatches(Block block, out Hash256? withdrawalsRoot) =>
   394→        ValidateWithdrawalsHashMatches(block.Header, block.Body, out withdrawalsRoot);
   395→
   396→    public static bool ValidateWithdrawalsHashMatches(BlockHeader header, BlockBody body, out Hash256? withdrawalsRoot)
   397→    {
   398→        if (body.Withdrawals is null)
   399→        {
   400→            withdrawalsRoot = null;
   401→            return header.WithdrawalsRoot is null;
   402→        }
   403→
   404→        return (withdrawalsRoot = new WithdrawalTrie(body.Withdrawals).RootHash) == header.WithdrawalsRoot;
   405→    }
   406→
   407→    private static string Invalid(Block block) =>
   408→        $"Invalid block {block.ToString(Block.Format.FullHashAndNumber)}:";
   409→}
